INSERT INTO competencies(id,domain_id,subject_id,curriculum_level_id,code,label,description,objectives,common_errors,official_reference_url,programme_version,effective_from) VALUES
 ('00000000-0000-0000-0000-000000000801','00000000-0000-0000-0000-000000000701','00000000-0000-0000-0000-000000000202','00000000-0000-0000-0000-000000000102','CM2-MATH-FRACTIONS','Comparer et calculer avec des fractions simples','Comprendre une fraction, la représenter et comparer des fractions simples.', '["Repérer le numérateur et le dénominateur","Comparer des fractions simples"]'::jsonb, '["Confondre numérateur et dénominateur","Comparer seulement les numérateurs"]'::jsonb,'https://www.education.gouv.fr/bo/2025/Hebdo32/MENE2519535A','programme-2025','2025-09-01'),
 ('00000000-0000-0000-0000-000000000802','00000000-0000-0000-0000-000000000701','00000000-0000-0000-0000-000000000202','00000000-0000-0000-0000-000000000102','CM2-MATH-PROPORTION','Résoudre un problème de proportionnalité','Utiliser un tableau ou un raisonnement pour trouver une valeur proportionnelle.', '["Reconnaître une situation de proportionnalité","Choisir une stratégie de calcul"]'::jsonb, '["Additionner au lieu de multiplier","Oublier l unité"]'::jsonb,'https://www.education.gouv.fr/bo/2025/Hebdo32/MENE2519535A','programme-2025','2025-09-01'),
